import { Component, input } from '@angular/core';
import { CurrencyPipe, DatePipe } from '@angular/common';

type TxStatus = 'pending' | 'posted' | 'reversed';
interface Transaction {
  id: string;
  occurredAt: string;
  description: string;
  amountMinor: number; // signed: negative is an outgoing transaction
  currency: 'INR';
  status: TxStatus;
}

@Component({
  selector: 'app-transaction-history',
  standalone: true,
  imports: [CurrencyPipe, DatePipe],
  template: `
    <h2>Recent transactions</h2>
    <ul>
      @for (tx of transactions(); track tx.id) {
        <li>
          <span>{{ tx.description }}</span>
          <time [attr.datetime]="tx.occurredAt">{{ tx.occurredAt | date:'mediumDate' }}</time>
          <strong>{{ tx.amountMinor / 100 | currency:tx.currency }}</strong>
          <span>Status: {{ tx.status }}</span>
        </li>
      } @empty {
        <li>No transactions available.</li>
      }
    </ul>
  `
})
export class TransactionHistoryComponent {
  readonly transactions = input.required<readonly Transaction[]>();
}
