import { Component, inject, signal } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { DestroyRef } from '@angular/core';

type Row = { id: string; description: string; amountMinor: number; currency: string };

@Component({
  selector: 'app-bank-transaction-search',
  standalone: true,
  imports: [ReactiveFormsModule],
  template: `
    <form [formGroup]="filters" (ngSubmit)="search()">
      <label>Account
        <select formControlName="accountId">
          <option value="">Choose account</option>
          <option value="acct-demo-1">Everyday account</option>
        </select>
      </label>
      <label>From <input type="date" formControlName="from" /></label>
      <label>To <input type="date" formControlName="to" /></label>
      <button type="submit" [disabled]="filters.invalid || loading()">Search</button>
    </form>
    @if (error()) { <p role="alert">{{ error() }}</p> }
    @if (loading()) { <p>Searching...</p> }
    @for (row of results(); track row.id) {
      <p>{{ row.description }}: {{ row.amountMinor }} minor units ({{ row.currency }})</p>
    } @empty {
      @if (!loading() && !error()) { <p>No results.</p> }
    }
  `
})
export class BankTransactionSearchComponent {
  private readonly http = inject(HttpClient);
  private readonly destroyRef = inject(DestroyRef);
  readonly loading = signal(false);
  readonly error = signal('');
  readonly results = signal<readonly Row[]>([]);
  readonly filters = new FormGroup({
    accountId: new FormControl('', { nonNullable: true, validators: [Validators.required] }),
    from: new FormControl('2026-10-01', { nonNullable: true, validators: [Validators.required] }),
    to: new FormControl('2026-10-31', { nonNullable: true, validators: [Validators.required] })
  });

  search(): void {
    if (this.filters.invalid) return;
    const { accountId, from, to } = this.filters.getRawValue();
    if (from > to) { this.error.set('Start date must not exceed end date.'); return; }
    this.error.set('');
    this.loading.set(true);
    const params = new HttpParams().set('accountId', accountId).set('from', from).set('to', to);
    this.http.get<readonly Row[]>('/api/transactions', { params })
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: rows => this.results.set(rows),
        error: () => { this.error.set('Search failed. Try again.'); this.loading.set(false); },
        complete: () => this.loading.set(false)
      });
  }
}
