import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, catchError, shareReplay, throwError } from 'rxjs';

interface BalanceSnapshot {
  accountId: string;
  postedMinor: number;
  availableMinor: number;
  currency: 'INR';
  updatedAt: string;
}

@Injectable({ providedIn: 'root' })
export class AccountSummaryQuery {
  private readonly http = inject(HttpClient);
  private cached$?: Observable<BalanceSnapshot>;

  get(): Observable<BalanceSnapshot> {
    if (!this.cached$) {
      this.cached$ = this.http.get<BalanceSnapshot>('/api/accounts/summary').pipe(
        catchError(error => {
          this.cached$ = undefined; // permit a later explicit retry
          return throwError(() => error);
        }),
        shareReplay({ bufferSize: 1, refCount: false })
      );
    }
    return this.cached$;
  }

  invalidate(): void {
    this.cached$ = undefined;
  }
}
