import { Component, DestroyRef, inject, signal } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';

type Summary = { postedMinor: number; availableMinor: number; currency: 'INR' };
type ViewState =
  | { kind: 'idle' | 'loading' }
  | { kind: 'ready'; data: Summary }
  | { kind: 'error'; message: string; retryable: boolean };

@Component({
  selector: 'app-account-summary',
  standalone: true,
  template: `
    <button (click)="load()" [disabled]="state().kind === 'loading'">Refresh</button>
    @switch (state().kind) {
      @case ('idle') { <p>Load your account summary.</p> }
      @case ('loading') { <p aria-live="polite">Loading balance...</p> }
      @case ('ready') {
        @if (readyData(); as data) {
          <p>Available: {{ data.availableMinor }} minor units ({{ data.currency }})</p>
        }
      }
      @case ('error') {
        <p role="alert">{{ errorMessage() }}</p>
      }
    }
  `
})
export class AccountSummaryComponent {
  private readonly http = inject(HttpClient);
  private readonly destroyRef = inject(DestroyRef);
  readonly state = signal<ViewState>({ kind: 'idle' });

  readyData(): Summary | null {
    const value = this.state();
    return value.kind === 'ready' ? value.data : null;
  }
  errorMessage(): string {
    const value = this.state();
    return value.kind === 'error' ? value.message : '';
  }
  load(): void {
    if (this.state().kind === 'loading') return;
    this.state.set({ kind: 'loading' });
    this.http.get<Summary>('/api/accounts/summary')
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: data => this.state.set({ kind: 'ready', data }),
        error: (err: HttpErrorResponse) => {
          const status = err.status;
          const message = status === 401 ? 'Please sign in again.'
            : status === 403 ? 'You cannot view this account.'
            : 'Balance temporarily unavailable. Please retry.';
          this.state.set({ kind: 'error', message, retryable: status === 0 || status >= 500 });
        }
      });
  }
}
